"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { archivoBlack, doHyeon } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "MAGNET";

/**
 * MAGNET 마그넷 — things that pull. The signature is the magnetic field: as
 * the pointer moves, every glyph in the wordmark and every magnetic pill
 * button computes its distance to the cursor and, within a radius, translates
 * toward it (damped in a rAF spring). Leave the field and everything eases
 * back to rest. Under reduced motion the field is inert — everything sits.
 *
 * `.magnet-js` is added on mount so the no-JS markup is the finished page:
 * wordmark and buttons at rest, copy readable.
 */
export default function MagnetPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const fieldRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("magnet-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "magnet" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Magnetic field. Each [data-magnet] element tracks the pointer and, within
  // RADIUS, translates toward it by STRENGTH of the offset. Damped per-frame.
  useEffect(() => {
    const field = fieldRef.current;
    if (!field || reduced) return;
    const els = Array.from(
      field.querySelectorAll<HTMLElement>("[data-magnet]"),
    );
    if (els.length === 0) return;

    const RADIUS = 160; // px — the reach of the field
    const STRENGTH = 0.32; // 0..1 — how far it pulls (0.32 = 32% of offset)

    const state = els.map((el) => ({
      el,
      tx: 0,
      ty: 0,
      cx: 0,
      cy: 0,
    }));

    let raf = 0;
    let active = false;

    const onMove = (e: PointerEvent) => {
      active = true;
      for (const s of state) {
        const r = s.el.getBoundingClientRect();
        const cx = r.left + r.width / 2;
        const cy = r.top + r.height / 2;
        const dx = e.clientX - cx;
        const dy = e.clientY - cy;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (!Number.isFinite(dist)) continue;
        if (dist < RADIUS) {
          // falloff: strongest at center, zero at the edge of the field
          const fall = 1 - dist / RADIUS;
          const f = Math.max(0, Math.min(1, fall));
          s.tx = dx * STRENGTH * f;
          s.ty = dy * STRENGTH * f;
        } else {
          s.tx = 0;
          s.ty = 0;
        }
      }
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const onLeave = () => {
      active = false;
      for (const s of state) {
        s.tx = 0;
        s.ty = 0;
      }
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      let moving = false;
      for (const s of state) {
        s.cx += (s.tx - s.cx) * 0.18;
        s.cy += (s.ty - s.cy) * 0.18;
        if (!Number.isFinite(s.cx)) s.cx = 0;
        if (!Number.isFinite(s.cy)) s.cy = 0;
        s.el.style.setProperty("--mg-x", `${s.cx.toFixed(2)}px`);
        s.el.style.setProperty("--mg-y", `${s.cy.toFixed(2)}px`);
        if (Math.abs(s.tx - s.cx) > 0.3 || Math.abs(s.ty - s.cy) > 0.3) {
          moving = true;
        }
      }
      if (moving || active) {
        raf = requestAnimationFrame(tick);
      } else {
        raf = 0;
      }
    };

    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerout", onLeave, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerout", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div
      ref={rootRef}
      className={`${archivoBlack.variable} ${doHyeon.variable} magnet-root`}
    >
      <div className="mg-blobs" aria-hidden="true" />
      <div ref={revealRef} className="mg-doc">
        <div ref={fieldRef} className="mg-field">
          <header className="mg-hero" data-reveal="">
            <p className="mg-kicker">
              <span lang="ko">마그넷 인터랙션 스튜디오</span> · MAGNETIC STUDIO · move me
            </p>
            <h1 className="mg-title" aria-label={TITLE}>
              <span aria-hidden="true" className="mg-title__row">
                {TITLE.split("").map((ch, i) => (
                  <span
                    key={i}
                    className="magnet-glyph"
                    data-magnet=""
                    style={{ "--mg-i": i } as CSSProperties}
                  >
                    {ch}
                  </span>
                ))}
              </span>
              <span lang="ko" className="mg-title__kr" aria-hidden="true">
                마그넷
              </span>
            </h1>
            <p className="mg-sub" data-reveal="">
              <span lang="ko">끌려오는 것.</span> Things that pull — drift your
              pointer over the letters and buttons; they lean in, then spring
              back when you leave.
            </p>
            <div className="mg-pills" data-reveal="">
              <button type="button" className="mg-pill" data-magnet="">
                <span lang="ko">끌어당김</span> · PULL
              </button>
              <button type="button" className="mg-pill mg-pill--ghost" data-magnet="">
                <span lang="ko">밀어냄</span> · PUSH
              </button>
              <button type="button" className="mg-pill mg-pill--ghost" data-magnet="">
                <span lang="ko">놓아줌</span> · RELEASE
              </button>
            </div>
          </header>
        </div>

        <section className="mg-how" aria-labelledby="mg-how-title">
          <div className="mg-sechead" data-reveal="">
            <p className="mg-eyebrow">
              02 — <span lang="ko">작동</span> · how it pulls
            </p>
            <h2 id="mg-how-title" className="mg-secthead__title">
              the field
            </h2>
            <p className="mg-secthead__kr" lang="ko">
              반경 안에서 끌고, 밖에서 놓아준다.
            </p>
          </div>
          <div className="mg-howgrid">
            <article className="mg-card" data-reveal="">
              <p className="mg-card__no">01</p>
              <h3 className="mg-card__h">
                <span lang="ko">반경</span> radius
              </h3>
              <p className="mg-card__b">
                <span lang="ko">포인터 160px 안에 들면 끌려간다.</span> Inside a
                160px radius, every element feels the pull.
              </p>
            </article>
            <article className="mg-card" data-reveal="">
              <p className="mg-card__no">02</p>
              <h3 className="mg-card__h">
                <span lang="ko">스프링</span> spring
              </h3>
              <p className="mg-card__b">
                <span lang="ko">부드럽게 끌리고, 부드럽게 돌아온다.</span> The
                motion is damped — it eases in and springs back out.
              </p>
            </article>
            <article className="mg-card" data-reveal="">
              <p className="mg-card__no">03</p>
              <h3 className="mg-card__h">
                <span lang="ko">놓아줌</span> release
              </h3>
              <p className="mg-card__b">
                <span lang="ko">벗어나면 제자리로.</span> Leave the field and
                every element returns exactly home.
              </p>
            </article>
          </div>
        </section>

        <footer className="mg-foot" data-reveal="">
          <p className="mg-foot__brand">
            MAGNET <span lang="ko">마그넷</span> ·{" "}
            <span lang="ko">끌려오는 것</span>
          </p>
          <p className="mg-foot__line">
            <span lang="ko">순수 코드 — 이미지 없음.</span> Pure code · no
            images · MIT
          </p>
        </footer>
      </div>
    </div>
  );
}

/* ==========================================================================
   MAGNET 마그넷 — things that pull · no.067
   playful-pop · bright-pink / hot-pink + ink-black · magnetic pointer field
   Scoped by convention to .magnet-root; classes prefixed mg- / magnet-.
   ========================================================================== */

.magnet-root {
  --mg-bg: #fff5f8;
  --mg-warm: #ffe9f0;
  --mg-cream: #fffafb;
  --mg-text: #1a0a12;
  --mg-mute: #7a5a68;
  --mg-quiet: #b896a4;
  --mg-pink: #ff3d77;
  --mg-pink-soft: rgba(255, 61, 119, 0.5);
  --mg-pink-faint: rgba(255, 61, 119, 0.14);
  --mg-ink: #160a10;
  --mg-font-display: var(--font-archivo-black), "Archivo Black", system-ui, sans-serif;
  --mg-font-kr: var(--font-do-hyeon), "Do Hyeon", sans-serif;
  --mg-ease: cubic-bezier(0.18, 1.2, 0.4, 1); /* a slight overshoot spring */

  position: relative;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(120% 90% at 50% 0%, rgba(255, 61, 119, 0.1), transparent 60%),
    radial-gradient(80% 60% at 50% 100%, rgba(255, 61, 119, 0.08), transparent 70%),
    linear-gradient(180deg, var(--mg-warm) 0%, var(--mg-bg) 50%, var(--mg-warm) 100%);
  color: var(--mg-text);
  font-family: var(--mg-font-kr);
  font-weight: 400;
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-x: clip;
}

.magnet-root :lang(ko) {
  font-family: var(--mg-font-kr);
}

.magnet-root ::selection {
  background: var(--mg-pink);
  color: #fff;
}

.magnet-root :focus-visible {
  outline: 2px solid var(--mg-pink);
  outline-offset: 3px;
}

/* ---- Atmospheric depth: soft pink blobs drifting behind all ---- */
.mg-blobs {
  position: fixed;
  inset: -10% -10% 0 -10%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(30% 36% at 18% 22%, rgba(255, 61, 119, 0.22), transparent 70%),
    radial-gradient(28% 34% at 82% 30%, rgba(255, 138, 180, 0.22), transparent 70%),
    radial-gradient(34% 40% at 60% 82%, rgba(255, 61, 119, 0.16), transparent 70%);
  filter: blur(30px);
  animation: mg-drift 22s ease-in-out infinite alternate;
}
@keyframes mg-drift {
  from { transform: translate3d(-2%, -1%, 0) scale(1); }
  to   { transform: translate3d(3%, 2%, 0) scale(1.06); }
}

.mg-doc {
  position: relative;
  z-index: 2;
  max-width: 1140px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}

/* ---- Reveal gating (JS-dependent pre-states) ---- */
.magnet-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--mg-ease), transform 800ms var(--mg-ease);
}
.magnet-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ---- Hero / the magnetic field ---- */
.mg-hero {
  padding: clamp(56px, 12vh, 120px) 0 clamp(28px, 5vh, 48px);
  text-align: center;
}
.mg-kicker {
  margin: 0 0 clamp(18px, 4vh, 32px);
  font-family: var(--mg-font-display);
  font-size: clamp(0.7rem, 1vw, 0.82rem);
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--mg-pink);
}
.mg-title {
  margin: 0 0 16px;
  font-family: var(--mg-font-display);
  font-weight: 400; /* Archivo Black only has 400 */
  font-size: clamp(3.4rem, 18vw, 15rem);
  line-height: 0.9;
  letter-spacing: -0.01em;
}
.mg-title__row {
  display: flex;
  justify-content: center;
  align-items: center;
}
.mg-title__kr {
  display: block;
  margin-top: 10px;
  font-family: var(--mg-font-kr);
  font-weight: 700;
  font-size: clamp(0.9rem, 2.4vw, 1.4rem);
  letter-spacing: 0.3em;
  color: var(--mg-mute);
}

/* The wordmark IS the concept: hot-pink solid glyphs that each pull toward
   the pointer. The pull is the --mg-x/--mg-y transform set from JS. */
.magnet-glyph {
  display: inline-block;
  color: var(--mg-pink);
  /* the spring press: a subtle pop that reads on hover/pull */
  text-shadow:
    0 6px 0 rgba(255, 61, 119, 0.16),
    0 14px 30px rgba(255, 61, 119, 0.2);
  transform: translate3d(var(--mg-x, 0), var(--mg-y, 0), 0);
  will-change: transform;
}

/* Glyph reveal (entrance). */
.magnet-js .magnet-glyph {
  opacity: 0;
  transform: translate3d(0, 0.35em, 0);
  transition: opacity 700ms var(--mg-ease), transform 700ms var(--mg-ease);
  transition-delay: calc(var(--mg-i) * 70ms + 150ms);
}
.magnet-js.is-mounted .magnet-glyph {
  opacity: 1;
  /* once mounted, transform is owned by the magnetic field vars */
  transform: translate3d(var(--mg-x, 0), var(--mg-y, 0), 0);
}

.mg-sub {
  margin: 22px auto 0;
  max-width: 44ch;
  font-size: clamp(0.98rem, 1.2vw, 1.1rem);
  color: var(--mg-mute);
}
.mg-sub :lang(ko) {
  color: var(--mg-text);
  font-weight: 500;
}

/* ---- Magnetic pills ---- */
.mg-pills {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 14px;
  margin-top: 34px;
}
.mg-pill {
  /* the pull: translate by --mg-x/--mg-y set from JS */
  --mg-x: 0;
  --mg-y: 0;
  transform: translate3d(var(--mg-x), var(--mg-y), 0);
  will-change: transform;
  font-family: var(--mg-font-display);
  font-size: clamp(0.82rem, 1.4vw, 1rem);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #fff;
  background: var(--mg-pink);
  border: 2px solid var(--mg-pink);
  padding: 14px 26px;
  border-radius: 999px;
  cursor: pointer;
  box-shadow:
    0 6px 0 rgba(255, 61, 119, 0.3),
    0 12px 26px rgba(255, 61, 119, 0.25);
  transition: background 180ms var(--mg-ease), color 180ms var(--mg-ease),
    box-shadow 180ms var(--mg-ease);
}
.mg-pill:hover {
  background: var(--mg-ink);
  border-color: var(--mg-ink);
}
.mg-pill:active {
  box-shadow: 0 2px 0 rgba(255, 61, 119, 0.3);
}
.mg-pill--ghost {
  color: var(--mg-pink);
  background: var(--mg-cream);
  box-shadow:
    0 6px 0 var(--mg-pink-faint),
    0 12px 26px rgba(255, 61, 119, 0.12);
}
.mg-pill--ghost:hover {
  color: #fff;
  background: var(--mg-pink);
  border-color: var(--mg-pink);
}

/* ---- Section headers ---- */
.mg-sechead {
  text-align: center;
  margin-bottom: clamp(24px, 4vh, 40px);
}
.mg-eyebrow {
  margin: 0 0 10px;
  font-family: var(--mg-font-display);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--mg-pink);
}
.mg-secthead__title {
  margin: 0 0 8px;
  font-family: var(--mg-font-display);
  font-weight: 400;
  font-size: clamp(1.7rem, 4vw, 2.6rem);
  text-transform: lowercase;
  letter-spacing: -0.01em;
  color: var(--mg-text);
}
.mg-secthead__kr {
  margin: 0;
  color: var(--mg-mute);
  font-size: 0.98rem;
}

/* ---- How grid ---- */
.mg-how {
  padding: clamp(24px, 5vh, 48px) 0;
}
.mg-howgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 18px;
}
.mg-card {
  padding: 26px 22px;
  border: 2px solid var(--mg-pink-faint);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(255, 233, 240, 0.6));
  text-align: left;
}
.mg-card__no {
  margin: 0 0 12px;
  font-family: var(--mg-font-display);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  color: var(--mg-pink);
}
.mg-card__h {
  margin: 0 0 8px;
  font-family: var(--mg-font-display);
  font-weight: 400;
  font-size: 1.1rem;
  color: var(--mg-text);
}
.mg-card__b {
  margin: 0;
  font-size: 0.92rem;
  color: var(--mg-mute);
  line-height: 1.7;
}
.mg-card__b :lang(ko) {
  color: var(--mg-text);
  font-weight: 500;
}

/* ---- Footer ---- */
.mg-foot {
  margin-top: clamp(40px, 8vh, 80px);
  padding: clamp(28px, 5vh, 48px) 0;
  border-top: 2px solid var(--mg-pink-faint);
  text-align: center;
}
.mg-foot__brand {
  margin: 0 0 6px;
  font-family: var(--mg-font-display);
  font-weight: 400;
  font-size: 0.9rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mg-text);
}
.mg-foot__line {
  margin: 0;
  font-size: 0.8rem;
  color: var(--mg-quiet);
}

/* ---- Reduced motion: field inert, everything sits at rest ---- */
@media (prefers-reduced-motion: reduce) {
  .mg-blobs { animation: none !important; }
  .magnet-js [data-reveal],
  .magnet-js .magnet-glyph {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .mg-pill { transform: none !important; }
}

@media (max-width: 560px) {
  .mg-pill { padding: 12px 20px; }
}
